 const topics=[{id:'word-study',rows:d.wordRows},...d.sections.map(s=>({id:s.id,rows:s._rows}))];
 const topicQuestions=topics.flatMap(t=>t.rows.map((r,i)=>question(`lesson-${n}-${t.id}-${i+1}`,t.id==='word-study'?'Word Study':'Grammar',t.id,r,i)));
 const grammarRows=d.sections.flatMap(s=>s._rows.map(row=>({topic:s.id,row})));
