 if(finalGrammar.length<10)finalGrammar.push(...d.sections.slice(0,10-finalGrammar.length).map(s=>s._rows[2]));
 const finalRows=[...d.readingRows.map(row=>({category:'Reading',row})),...finalVocab.map(v=>({category:'Vocabulary',row:vocabRows([v],required)[0]})),...finalGrammar.map(row=>({category:'Grammar',row})),...d.cultureRows.map(row=>({category:'Greek World',row}))];
 const banner={image:`assets/lesson-${n}-banner.png`,alt:`AI-generated educational reconstruction for Lesson ${n}: ${title}; illustrative scene rather than an eyewitness image`,caption:`${title}. AI-generated educational reconstruction of the adapted lesson setting; the image is illustrative and does not establish historical appearance or exact events.`};
 const sourceCitation=d.sources.map(([label,url])=>`${label}. ${url}`).join('\n');
 const lesson={id:`lesson-${n}`,number:n,title,greekTitle:d.greekTitle,scope:d.scope,theme:d.theme,module:'ἀνδρεία — Courage and Leadership',banner,
   pages:[{page:1,slug:`lesson-${n}-page-1`,title:'Reading',template:'reading',showTranslation:false},{page:2,slug:`lesson-${n}-page-2`,title:'Language Study',template:'grammar'},{page:3,slug:`lesson-${n}-page-3`,title:d.cultureTitle,template:'culture'}],
   vocabulary:d.vocab,
   reading:{title:d.readingTitle,audioPlaceholder:'Reading audio has not yet been recorded.',introduction:d.intro,paragraphs:d.paras.map(({greek,gloss})=>({greek,gloss})),translation:d.paras.map(p=>p.translation).join('\n\n'),sourceCitation,notesMarkdown:'Source and adaptation boundaries are stated in the introduction. All Greek is course-adapted present-tense narrative, not a verbatim ancient extract. Blue glosses support forms beyond the taught grammar; those untaught constructions are not assessed as morphology or production targets.'},
   wordStudy:{label:'Word Study — '+({13:'Protection and Responsibility',14:'Experience and Practical Judgment',15:'Travel, Contests, and Pay',16:'Resources and Persuasion'}[n]),blocks:[{title:'Words in the Reading',practiceTopic:'word-study',body:d.wordBody,display:d.wordDisplay.map(([greek,english])=>({greek,english}))}]},
   grammar:{intro:`${d.scope}. Work through each section, use its checks and topic practice, then complete the grammar exercises. Reading-only forms remain supported by glosses.`,objectives:objectives[n],sections:d.sections.map(({_rows,...s})=>s),summary:{title:'Grammar Summary',items:summaries[n]}},
   culture:{title:d.cultureTitle,body:[],sections:d.culture.map(([title,body])=>({title,body})),questions:d.cultureQuestions.map(([prompt,answer])=>({prompt,answer})),review:{title:'Before the Final Quiz',items:[...summaries[n],...d.cultureQuestions.slice(-2).map(([p,a])=>`${p} ${a}`)]},sources:d.sources.map(([title,url])=>({title,url}))},
   enrichment:[],activities:{
     'vocab-flashcards':{title:`Lesson ${n} Vocabulary Flashcards`,cards:entries.map(v=>({prompt:`${v.greek} — ${v.status}`,answer:`${v.english}; ${v.dictionaryForm}`}))},
     'vocab-practice':{title:`Lesson ${n} Vocabulary Practice`,practiceMode:'rounds',roundSize:10,threshold:80,instructions:'Practice required words in short rounds. Reading vocabulary remains supported by glosses.',questions:vocabQuestions},
     'grammar-flashcards':{title:`Lesson ${n} Grammar Flashcards`,cards:d.sections.flatMap(s=>s.checks.map(c=>({prompt:c.prompt,answer:c.answer})))},
     'topic-practice':{title:`Lesson ${n} Word Study and Grammar Topic Practice`,practiceMode:'rounds',roundSize:10,instructions:'Choose a topic. Every teaching section has its own practice questions with immediate feedback.',questions:topicQuestions},
     'grammar-exercises':{title:`Lesson ${n} Grammar Exercises`,description:d.scope,threshold:80,required:true,requireAllAnswers:true,revision:`lesson-${n}-grammar-exercises-module-2-v1`,instructions:'Answer every question and score at least 80% to continue to the culture page.',questions:grammarQuestions},
     'lesson-quiz':{title:`Lesson ${n} Final Quiz — ${title}`,description:'Reading, vocabulary, taught grammar, and the Greek world',threshold:80,required:true,requireAllAnswers:true,revision:`lesson-${n}-final-quiz-module-2-v1`,pointsPossible:30,instructions:`Answer all 30 questions and score at least 80% to complete Lesson ${n}.`,questions:finalRows.map(({category,row},i)=>question(`lesson-${n}-final-${i+1}`,category,null,row,i))}
   },previousLesson:{id:`lesson-${n-1}`,title:titles[n-1],fallbackUrl:`lesson.html?lesson=${n-1}&page=1`},nextLesson:{id:`lesson-${n+1}`,title:titles[n+1],fallbackUrl:`lesson.html?lesson=${n+1}&page=1`},contentRevision:`lesson-${n}-module-2-v1`
 };
 // Content-level authoring checks: never silently emit a partial lesson.
 if(d.paras.length<6||d.paras.length>8||lesson.reading.translation.split('\n\n').length!==d.paras.length)throw Error(`Paragraph alignment ${n}`);
