 console.log(`Lesson ${n}: ${d.paras.length} paragraphs; ${entries.length} vocabulary (${required.length} required); ${d.sections.length} grammar sections; ${topicQuestions.length} topic; ${grammarQuestions.length} required grammar; ${finalRows.length} final quiz.`);
